#include <stdint.h>
#include <stdbool.h>

/* 20! is the largest factorial that fits in uint64_t. */
uint64_t factorial(unsigned n) {
    if (n <= 1) return 1;            /* base case: covers 0 and 1. */
    return n * factorial(n - 1);     /* progress: n shrinks by 1. */
}

bool safe_factorial(int n, uint64_t *out) {
    if (n < 0 || n > 20) return false;   /* bound depth and overflow. */
    *out = factorial((unsigned)n);
    return true;
}
```

```text
factorial(4)
  4 * factorial(3)
      3 * factorial(2)
          2 * factorial(1)  -> 1 (base case)
          = 2
      = 6
  = 24
```

